stration'=>'Kuidas seadistada WP kasutajate registreerimist','Allow Only logged in users to view all entries'=>'Lubada ainult sisse logitud kasutajatel vaadata kõiki kirjeid','Allow logged in users to edit form entries'=>'Lubada sisse logitud kasutajatel redigeerida vormi kirjeid','Allow to Configure Global Validation Message'=>'Lubada seadistada ülemaailmset valideerimissõnumit','How to add Custom CSS/JS'=>'Kuidas lisada kohandatud CSS/JS']];